int: n = 20; % number of steps in the stair
int: m1 = 3;
int: m2 = 5;

% Possible step sizes: 3, 4, 5
set of int: StepSizes = m1..m2;

% At most n moves (in the worst case, all 1-steps, but here min is 3)
array[1..n] of var 0..m2: steps;

% Each move is either 0 (no move) or a valid step size
constraint forall(i in 1..n) (
    steps[i] = 0 \/ (steps[i] >= m1 /\ steps[i] <= m2)
);

% The sum of all steps must be exactly n
constraint sum(i in 1..n)(steps[i]) = n;

% After reaching the top, all further moves must be 0
% Find the first zero, then all after must be zero
array[1..n] of var bool: is_zero;
constraint forall(i in 1..n) (is_zero[i] <-> (steps[i] = 0));
constraint forall(i, j in 1..n where i < j) (
    is_zero[i] -> is_zero[j]
);

solve satisfy;

output [
    "{",
    "\"steps\": [" ++ join(",", [show(steps[i]) | i in 1..n]) ++ "]",
    "}"
];
```

