int: num_cows = 25;
int: num_sons = 5;
array[1..num_cows] of int: milk = [i | i in 1..num_cows];
array[1..num_sons] of int: cows_per_son = [7,6,5,4,3];

% cow_assignments[i] = s means cow i is assigned to son s+1 (0-based for output)
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Each son gets the right number of cows
constraint
  forall(s in 0..num_sons-1) (
    count(cow_assignments, s) = cows_per_son[s+1]
  );

% Each son gets the same total milk
array[1..num_sons] of var int: milk_per_son;
constraint
  forall(s in 0..num_sons-1) (
    milk_per_son[s+1] = sum([milk[i] | i in 1..num_cows where cow_assignments[i] = s])
  )
  /\
  forall(s in 2..num_sons) (
    milk_per_son[s] = milk_per_son[1]
  );

solve satisfy;

output [
  "{",
  "\"cow_assignments\": [" ++ join(",", [show(cow_assignments[i]) | i in 1..num_cows]) ++ "]",
  "}"
];
```

