constraint
    forall(i in PEOPLE) (
        transplants[i,i] = 0
    );

% Each person can donate at most one kidney
constraint
    forall(i in PEOPLE) (
        sum(j in PEOPLE)(transplants[i,j]) <= 1
    );

% Each person can receive at most one kidney
constraint
    forall(j in PEOPLE) (
        sum(i in PEOPLE)(transplants[i,j]) <= 1
    );

% Anyone who donates must also receive
constraint
    forall(i in PEOPLE) (
        sum(j in PEOPLE)(transplants[i,j]) <= sum(k in PEOPLE)(transplants[k,i])
    );

% Objective: maximize the number of people who receive a kidney
var int: num_receivers = sum(j in PEOPLE)(min(1, sum(i in PEOPLE)(transplants[i,j])));
solve maximize num_receivers;

output [
    "{",
    "\"transplants\": [",
    join(",\n", [
        "[" ++ join(",", [show(transplants[i,j]) | j in PEOPLE]) ++ "]"
        | i in PEOPLE
    ]),
    "]",
    "}"
];
