% Job Shop Scheduling Problem

% Input data
% jobs_data = [  # (job_id, task_id) -> (machine_id, duration)
%     [(0, 3), (1, 2), (2, 2)],  # Job 0
%     [(0, 2), (2, 1), (1, 4)],  # Job 1
%     [(1, 4), (2, 3)]           # Job 2
% ]

int: num_jobs = 3;
array[1..num_jobs] of int: num_tasks = [3,3,2];
int: num_machines = 3;

% Flattened data for easier access
array[1..num_jobs, 1..max(num_tasks)] of int: machine = 
  array2d(1..num_jobs, 1..max(num_tasks), [
    1, 2, 3,   % Job 0: machines (1-based)
    1, 3, 2,   % Job 1
    2, 3, 0    % Job 2 (pad with 0 for unused task)
  ]);
array[1..num_jobs, 1..max(num_tasks)] of int: duration = 
  array2d(1..num_jobs, 1..max(num_tasks), [
    3, 2, 2,   % Job 0: durations
    2, 1, 4,   % Job 1
    4, 3, 0    % Job 2 (pad with 0 for unused task)
  ]);

% Decision variables: start time for each task
array[1..num_jobs, 1..max(num_tasks)] of var 0..100: start;

% Makespan variable
var 0..100: makespan;

% Each job's tasks must be done in order
constraint
  forall(j in 1..num_jobs) (
    forall(t in 1..num_tasks[j]-1) (
      start[j, t+1] >= start[j, t] + duration[j, t]
    )
  );

% No overlap on the same machine
