    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
];

% Find all X cells
set of int: ROWS = 1..8;
set of int: COLS = 1..8;

array[ROWS, COLS] of var 0..1: mines;

% Only X cells can be mines, others must be 0
constraint
  forall(r in ROWS, c in COLS where game_data[r,c] != X) (
    mines[r,c] = 0
  );

% For each clue cell, the sum of mines in its 8 neighbors must equal the clue
constraint
  forall(r in ROWS, c in COLS where game_data[r,c] != X) (
    let {
      set of int: RR = {rr | rr in r-1..r+1 where rr in ROWS};
      set of int: CC = {cc | cc in c-1..c+1 where cc in COLS};
      set of (int,int): NBR = {(rr,cc) | rr in RR, cc in CC, not (rr = r /\ cc = c)}
    } in
      sum([(mines[rr,cc]) | (rr,cc) in NBR]) = game_data[r,c]
  );

output [
  "{\n\"mines\": [\n" ++
  join(",\n", [
    "  [" ++ join(",", [show(fix(mines[r,c])) | c in COLS]) ++ "]"
    | r in ROWS
  ]) ++
  "\n]\n}"
