int: N = 20;

array[1..3, 1..3] of int: puzzle_start = 
    array2d(1..3, 1..3, [
        0, 3, 6,
        2, 4, 8,
        1, 7, 5
    ]);

array[1..3, 1..3] of int: puzzle_end = 
    array2d(1..3, 1..3, [
        1, 2, 3,
        4, 5, 6,
        7, 8, 0
    ]);

set of int: Tiles = 0..8;
set of int: Pos = 1..3;
set of int: Step = 1..N+1;

% The state of the puzzle at each step
array[Step, Pos, Pos] of var Tiles: steps;

% Each state is a permutation of 0..8
constraint
    forall(s in Step) (
        alldifferent([steps[s, i, j] | i in Pos, j in Pos])
    )
    /\
    forall(s in Step) (
        forall(i in Pos, j in Pos) (
            steps[s, i, j] >= 0 /\ steps[s, i, j] <= 8
        )
    );

% Initial and final state
constraint
    forall(i in Pos, j in Pos) (
        steps[1, i, j] = puzzle_start[i, j] /\
        steps[N+1, i, j] = puzzle_end[i, j]
    );

% Only one move per step: the empty tile (0) swaps with an adjacent tile
predicate is_adjacent(int: r1, int: c1, int: r2, int: c2) =
    (abs(r1 - r2) = 1 /\ c1 = c2) \/ (abs(c1 - c2) = 1 /\ r1 = r2);

% For each step, enforce a valid move
constraint
    forall(s in 1..N) (
        let {
            % Find the position of 0 in step s and s+1
            var Pos: r0_s = arg_min([if steps[s, i, j] = 0 then 1 else 0 endif | i in Pos, j in Pos], 9) div 3 + 1,
            var Pos: c0_s = arg_min([if steps[s, i, j] = 0 then 1 else 0 endif | i in Pos, j in Pos], 9) mod 3 + 1,
            var Pos: r0_sp = arg_min([if steps[s+1, i, j] = 0 then 1 else 0 endif | i in Pos, j in Pos], 9) div 3 + 1,
            var Pos: c0_sp = arg_min([if steps[s+1, i, j] = 0 then 1 else 0 endif | i in Pos, j in Pos], 9) mod 3 + 1
        } in
        % The empty tile moves to an adjacent position
        is_adjacent(r0_s, c0_s, r0_sp, c0_sp) /\
        % All other tiles remain the same except the swapped one
        let {
            var int: moved_tile = steps[s, r0_sp, c0_sp]
        } in
        forall(i in Pos, j in Pos) (
            if (i = r0_s /\ j = c0_s) then
                steps[s+1, i, j] = moved_tile
            else if (i = r0_sp /\ j = c0_sp) then
                steps[s+1, i, j] = 0
            else
                steps[s+1, i, j] = steps[s, i, j]
            endif
        )
    );

output [
    "{\n\"steps\": [\n" ++
    join(",\n", [
        "[\n" ++
        join(",\n", [
            "[" ++ join(",", [show(steps[s, i, j]) | j in Pos]) ++ "]"
            | i in Pos
        ]) ++
        "\n]"
        | s in Step
    ]) ++
    "\n]\n}"
];
