% Convert date strings to integer days (days since 2024-05-01)
function int: date_to_int(string: d) =
    let {
        array[1..3] of int: parts = [ 
            str_to_int(substr(d,1,4)), 
            str_to_int(substr(d,6,2)), 
            str_to_int(substr(d,9,2))
        ]
    } in
