    2, 3, 1, 2,   % [TWO, STRIPED, RED, RECT]
    3, 3, 3, 1,   % [THREE, STRIPED, GREEN, DIAMOND]
    3, 1, 1, 1,   % [THREE, FULL, RED, DIAMOND]
    1, 3, 3, 1,   % [ONE, STRIPED, GREEN, DIAMOND]
    1, 2, 1, 1,   % [ONE, EMPTY, RED, DIAMOND]
    2, 1, 2, 1,   % [TWO, FULL, PURPLE, DIAMOND]
    3, 1, 2, 3,   % [THREE, FULL, PURPLE, ELLIPSE]
    3, 1, 3, 2,   % [THREE, FULL, GREEN, RECT]
    1, 1, 2, 1,   % [ONE, FULL, PURPLE, DIAMOND]
    1, 3, 2, 1,   % [ONE, STRIPED, PURPLE, DIAMOND]
    1, 1, 3, 2    % [ONE, FULL, GREEN, RECT]
];

% Indices of the three cards in the set (1-based)
array[1..3] of var 1..num_cards: winning_cards;

% All cards must be different
constraint
    all_different(winning_cards);

% For each feature, the three cards must be all the same or all different
constraint
    forall(f in 1..num_features) (
        let {
            var int: v1 = cards_data[winning_cards[1], f],
            var int: v2 = cards_data[winning_cards[2], f],
            var int: v3 = cards_data[winning_cards[3], f]
        } in
            (v1 = v2 /\ v2 = v3) \/
            (all_different([v1, v2, v3]))
    );

% To avoid symmetric solutions, enforce increasing order
constraint
    winning_cards[1] < winning_cards[2] /\
    winning_cards[2] < winning_cards[3];

solve satisfy;

output [
    "{",
    "\"winning_cards\": [" ++
        join(", ", [show(winning_cards[i]) | i in 1..3]) ++
    "]",
    "}"
];
