int: n_templates = 2; % Number of templates
int: n_var = 7; % Number of different variations
array[1..n_var] of int: demand = [250, 255, 260, 500, 500, 800, 1100];

% Decision variables
array[1..n_templates, 1..n_slots] of var 0..n_var: layout; 
% layout[t,s] = v means slot s on template t is assigned to variation v (0 = empty slot)

array[1..n_templates] of var 0..1000: sheets; 
% Number of times template t is printed

% For each template and variation, count how many times variation v appears on template t
array[1..n_templates, 1..n_var] of var 0..n_slots: var_on_template;
constraint
  forall(t in 1..n_templates, v in 1..n_var) (
    var_on_template[t,v] = count([layout[t,s] | s in 1..n_slots], v)
  );

% For each variation, total produced must be at least demand
constraint
  forall(v in 1..n_var) (
    sum(t in 1..n_templates)(var_on_template[t,v] * sheets[t]) >= demand[v]
  );

% No slot can be assigned to more than one variation
% (already enforced by the layout variable's domain)

% Each slot is either empty (0) or assigned to a variation (1..n_var)
% (already enforced by the domain)

% Try to minimize overproduction (total produced - total demand)
var int: overproduction = sum(v in 1..n_var)(
  sum(t in 1..n_templates)(var_on_template[t,v] * sheets[t]) - demand[v]
);

