int: size = 10;

% The positions of the marks, 0 = a_1 < a_2 < ... < a_size
array[1..size] of var 0..1000: marks;

% The length of the ruler is the last mark
var 0..1000: length = marks[size];

% The marks are strictly increasing, and the first is 0
constraint marks[1] = 0;
constraint forall(i in 1..size-1) (marks[i] < marks[i+1]);

% All pairwise differences must be distinct
int: num_diffs = size * (size - 1) div 2;
array[1..num_diffs] of var 1..1000: diffs;

% Map each difference to a pair (i, j) with i < j
% We'll use a helper array to map k to (i, j)
array[1..num_diffs] of int: diff_i = [i | i in 1..size-1, j in i+1..size];
array[1..num_diffs] of int: diff_j = [j | i in 1..size-1, j in i+1..size];

constraint
    forall(k in 1..num_diffs) (
        diffs[k] = marks[diff_j[k]] - marks[diff_i[k]]
    );

constraint
    all_different(diffs);

% Symmetry breaking: first difference < last difference
constraint (marks[2] - marks[1]) < (marks[size] - marks[size-1]);

% Objective: minimize the length of the ruler
solve minimize length;

output [
    "{",
    "\"marks\": [" ++ join(",", [show(marks[i]) | i in 1..size]) ++ "], ",
    "\"length\": " ++ show(length),
    "}"
];
