constraint
  forall(w in 1..n_weeks) (
    alldifferent([assign[w,g,s] | g in 1..n_groups, s in 1..group_size])
  );

% Each group has unique golfers
constraint
  forall(w in 1..n_weeks, g in 1..n_groups) (
    alldifferent([assign[w,g,s] | s in 1..group_size])
  );

% No pair of golfers plays together more than once
array[1..n_golfers, 1..n_golfers] of var 0..n_weeks: together;

constraint
  forall(i,j in 1..n_golfers where i < j) (
    together[i,j] = sum([
