        exists(w in 1..n_weeks, g in 1..n_groups) (
          exists(s1 in 1..group_size, s2 in 1..group_size where s1 != s2) (
            assign[w,g,s1] = i /\ assign[w,g,s2] = j
          )
        )
      )
    ])
