int: cols = 13;
int: col_rule_len = 2;
array[1..cols, 1..col_rule_len] of int: col_rules = 
[
    [0, 2],
    [2, 1],
    [3, 2],
    [0, 6],
    [1, 4],
    [0, 3],
    [0, 4],
    [0, 4],
    [0, 4],
    [0, 5],
    [0, 4],
    [1, 3],
    [0, 2]
];

array[1..rows, 1..cols] of var 0..1: board;

% Helper predicate: for a given line and its rule, enforce the nonogram constraints
predicate nonogram_line(array[int] of var 0..1: line, array[int] of int: rule) =
    let {
        int: n = length(line),
        int: k = length(rule),
        array[1..k] of int: blocks = [r | r in rule where r > 0],
        int: num_blocks = sum([if r > 0 then 1 else 0 endif | r in rule])
    } in
    if num_blocks == 0 then
        forall(i in 1..n)(line[i] = 0)
    else
        let {
            int: m = length(blocks),
            array[1..m] of var 1..n: start, % start positions of each block
            array[1..m] of int: block_len = blocks
        } in
        % Blocks must be in order and not overlap
        constraint
            forall(b in 1..m)(
                start[b] + block_len[b] - 1 <= n
            ) /\
            forall(b in 1..m-1)(
                start[b+1] > start[b] + block_len[b] - 1
            ) /\
            % Each block must be filled
            forall(b in 1..m)(
                forall(i in 0..block_len[b]-1)(
                    line[start[b]+i] = 1
                )
            ) /\
            % All other cells must be empty
            forall(i in 1..n)(
                exists(b in 1..m)(
                    i >= start[b] /\ i < start[b] + block_len[b]
                ) \/ line[i] = 0
            )
        endif
    endif;

% Apply row rules
constraint
    forall(r in 1..rows) (
        nonogram_line([board[r, c] | c in 1..cols], row_rules[r, 1..row_rule_len])
    );

% Apply column rules
constraint
    forall(c in 1..cols) (
        nonogram_line([board[r, c] | r in 1..rows], col_rules[c, 1..col_rule_len])
    );

output [
    "{\n\"board\": [\n",
    join(",\n", [
        "  [" ++ join(",", [show(board[r, c]) | c in 1..cols]) ++ "]"
        | r in 1..rows
    ]),
    "\n]\n}"
];
