```minizinc
int: n_boats = 5;
int: n_periods = 4;
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

% Decision variables
array[1..n_boats] of var bool: is_host; % is_host[b] = 1 if boat b is a host

% visits[g,h,p] = 1 if guest boat g visits host h at period p
array[1..n_boats, 1..n_boats, 1..n_periods] of var bool: visits;

% 1. A boat cannot visit itself
constraint forall(g in 1..n_boats, p in 1..n_periods) (
    visits[g,g,p] = false
);

% 2. Only host boats can be visited
constraint forall(g in 1..n_boats, h in 1..n_boats, p in 1..n_periods where g != h) (
    visits[g,h,p] <= is_host[h]
);

% 3. Each guest boat visits exactly one host per period, unless it is a host itself (hosts stay on their own boat)
constraint forall(g in 1..n_boats, p in 1..n_periods) (
    (is_host[g] = 1 /\ forall(h in 1..n_boats where h != g)(visits[g,h,p] = 0)) \/
    (is_host[g] = 0 /\ sum([visits[g,h,p] | h in 1..n_boats where h != g]) = 1)
);

% 4. A guest cannot visit the same host more than once
constraint forall(g in 1..n_boats, h in 1..n_boats where g != h) (
    sum([visits[g,h,p] | p in 1..n_periods]) <= 1
);

% 5. Guest crews cannot meet more than once
% For each pair of guest boats (g1,g2), count the number of periods where they are on the same host
constraint forall(g1 in 1..n_boats, g2 in 1..n_boats where g1 < g2) (
    sum([sum([visits[g1,h,p] * visits[g2,h,p] | h in 1..n_boats where h != g1 /\ h != g2]) | p in 1..n_periods]) <= 1
);

% 6. Capacity constraints: For each host h and period p, total people on board <= capacity
constraint forall(h in 1..n_boats, p in 1..n_periods) (
    is_host[h] = 1 ->
    (crew_size[h] + sum([crew_size[g] * visits[g,h,p] | g in 1..n_boats where g != h])) <= capacity[h]
);

% 7. Guests cannot host
constraint forall(g in 1..n_boats) (
    is_host[g] = 0 -> sum([visits[g,h,p] | h in 1..n_boats, p in 1..n_periods]) > 0
);

% Objective: Minimize the number of host boats
solve minimize sum(is_host);

output [
    "{",
    "\"is_host\": [" ++ join(",", [show(is_host[b]) | b in 1..n_boats]) ++ "],",
    "\"visits\": ["
] ++
[
    "[" ++ join(",", [
        "[" ++ join(",", [
            show(visits[g,h,p])
            | h in 1..n_boats
        ]) ++ "]"
        | p in 1..n_periods
    ]) ++ "]"
    | g in 1..n_boats
] ++ [
    "]",
    "}"
];
