% Langford's Number Problem L(k, n)
% Input: k = 4 (number of sets)
% Find the smallest n for which a solution exists, or solve for a given n.

int: k = 4;
int: n = 7; % For k=4, the smallest n for which a solution exists is 7 (known result)

int: len = k * n;

% The sequence: solution[i] is the number at position i (1-based)
array[1..len] of var 1..n: solution;

% For each number m in 1..n, and each copy c in 1..k, let pos[m,c] be the position of the c-th occurrence of m
array[1..n, 1..k] of var 1..len: pos;

% Each position in the sequence is filled exactly once
constraint all_different([pos[m,c] | m in 1..n, c in 1..k]);

% Each number appears k times in the solution
constraint
    forall(m in 1..n) (
        forall(c in 1..k) (
            solution[pos[m,c]] = m
        )
    );

% For each number m, the positions of its k occurrences must be spaced m+1 apart
% That is, for each pair of consecutive occurrences, pos[m,c+1] = pos[m,c] + m + 1
constraint
    forall(m in 1..n) (
        forall(c in 1..k-1) (
            pos[m,c+1] = pos[m,c] + m + 1
        )
    );

% All positions must be within the sequence
constraint
    forall(m in 1..n, c in 1..k) (
        pos[m,c] >= 1 /\ pos[m,c] <= len
    );

% Symmetry breaking: fix the first occurrence of the largest number to the first position
constraint pos[n,1] = 1;

solve satisfy;

output [
    "{\n",
    "\"position\": [", join(",", [show(pos[m,c]) | m in 1..n, c in 1..k]), "],\n",
    "\"solution\": [", join(",", [show(solution[i]) | i in 1..len]), "]\n",
    "}"
];
