% Parameters
int: n = 8; % Number of words to find
int: len = 8; % Length of each word
set of int: ALPH = 1..4; % 1:A, 2:C, 3:G, 4:T

% Mapping for output
array[ALPH] of string: alphastr = ["A", "C", "G", "T"];

