constraint
  forall(i in 1..n) (
    sum([bool2int(words[i,j] = 2 \/ words[i,j] = 3) | j in 1..len]) = 4
  );

% Each pair of distinct words differ in at least 4 positions (Hamming distance)
constraint
  forall(i, j in 1..n where i < j) (
    sum([bool2int(words[i,k] != words[j,k]) | k in 1..len]) >= 4
  );

% Watson-Crick complement: 1<->4, 2<->3
function int: wc(int: x) =
  if x = 1 then 4
  else if x = 2 then 3
  else if x = 3 then 2
  else 1 endif endif endif;

