array[OPS] of var OPS: order2; % order applied to h to get m

% All operations used exactly once in each order
constraint all_different(order1);
constraint all_different(order2);

% The orders must be different
constraint exists(i in OPS)(order1[i] != order2[i]);

% Helper function to apply an operation
function var int: apply_op(var int: x, int: op) =
    if op = 1 then x + 2
    elseif op = 2 then x div 8
    elseif op = 3 then x - 3
    else x * 7 endif;

% Apply the sequence of operations
function var int: apply_ops(var int: x, array[int] of var int: ops) =
