        var int: s4 = apply_op(s3, ops[4])
    } in s4;

% m to h
constraint h = apply_ops(m, order1);
% h to m
constraint m = apply_ops(h, order2);

% Ages must be different
constraint m != h;

solve satisfy;

output [
    "{",
    "\"m\": ", show(m), ", ",
    "\"h\": ", show(h),
