int: n = 5;
int: N = n * n;

% x[i,j] is the number placed at cell (i,j), 1..N
array[1..n, 1..n] of var 1..N: x;

% For each number k (1..N), store its position (row, col)
array[1..N] of var 1..n: row;
array[1..N] of var 1..n: col;

% Link x and (row,col) variables
constraint
    forall(i in 1..n, j in 1..n) (
        exists(k in 1..N) (
            x[i,j] = k /\
            row[k] = i /\
            col[k] = j
        )
    )
    /\
    forall(k in 1..N) (
        x[row[k], col[k]] = k
    );

% All numbers must be placed exactly once
constraint
    alldifferent([x[i,j] | i in 1..n, j in 1..n]);

% All positions must be unique
constraint
    alldifferent([n*(row[k]-1) + col[k] | k in 1..N]);

% Movement constraints
constraint
    forall(k in 1..N-1) (
        let {
            var int: dr = abs(row[k+1] - row[k]),
            var int: dc = abs(col[k+1] - col[k])
        } in
        (
            % Type I: horizontal or vertical, exactly 3 away
            ((dr = 3 /\ dc = 0) \/ (dr = 0 /\ dc = 3))
            \/
            % Type II: diagonal, exactly 2 away
            ((dr = 2 /\ dc = 2))
        )
    );

output [
    "[\n" ++
    join(",\n", [ "[" ++ join(", ", [ show(x[i,j]) | j in 1..n ]) ++ "]" | i in 1..n ]) ++
    "\n]"
];
```

