  forall(i in 1..n) (
    sum(j in 1..n)(x[i,j]) = k
  );

% Constraint 2: Each column has exactly k coins
constraint
  forall(j in 1..n) (
    sum(i in 1..n)(x[i,j]) = k
  );

% Objective: Minimize the sum of squared horizontal distances from the main diagonal
% For cell (i,j), the horizontal distance from the main diagonal is |i-j|
% The quadratic distance is (i-j)^2
var int: z = sum(i in 1..n, j in 1..n)(x[i,j] * (i-j)*(i-j));

solve minimize z;

output [
